# Los pedazos de JS que viven afuera para poder probarse se pegan aca.
# Las marcas de Jinja de FID_JS van dentro de un comentario de JS: Jinja las
# procesa igual, y los tests que corren el <script> crudo en node (sin pasar
# por Jinja) ven un comentario en vez de un "{%" suelto que no compila.
DASHBOARD_HTML = DASHBOARD_HTML.replace("/*ESC_JS*/", ESC_JS).replace(
    "/*WA_MEDIOS_JS*/", WA_MEDIOS_JS
).replace("/*FID_JS*/", "/* {% raw %} */" + FID_JS + "/* {% endraw %} */"
).replace("/*PLEXO_JS*/", PLEXO_JS)


_calendly_sync_state = {"at": 0.0}
_calendly_sync_lock = threading.Lock()
CALENDLY_SYNC_EVERY = int(os.environ.get("CALENDLY_SYNC_EVERY", "600"))


def _maybe_sync_calendly(db_path: str) -> None:
    """Trae los leads de Calendly cuando alguien abre el CRM.

    La máquina de Fly se duerme sin tráfico, así que un cron interno no
    correría. Va en un hilo aparte para no demorar la carga de la página, y
    con throttle para no pegarle a Google en cada request.
    """
    if not os.environ.get("GMAIL_REFRESH_TOKEN"):
        return
    now = time.time()
    with _calendly_sync_lock:
        if now - _calendly_sync_state["at"] < CALENDLY_SYNC_EVERY:
            return
        _calendly_sync_state["at"] = now

    def _run():
        try:
            # Gmail primero: aporta el mail del invitado y el calendario, que
            # es el único que ve las cancelaciones, pasa después.
            from services.calendly_gcal import fetch_and_sync
            from services.calendly_gmail import fetch_and_sync_gmail
            g = fetch_and_sync_gmail(db_path)
            c = fetch_and_sync(db_path)
            if g["created"] or c["created"] or c["canceled"]:
                logging.getLogger(__name__).info(
                    "calendly sync: %s nuevas por mail, %s por calendario, %s canceladas",
                    g["created"], c["created"], c["canceled"])
        except Exception:
            logging.getLogger(__name__).warning("calendly sync falló", exc_info=True)

    threading.Thread(target=_run, daemon=True).start()


_notion_sync_state = {"at": 0.0}
_notion_sync_lock = threading.Lock()
NOTION_SYNC_EVERY = int(os.environ.get("NOTION_SYNC_EVERY", "600"))


def _maybe_sync_notion(db_path: str) -> None:
    """Trae los cambios de estado del tablero de Notion cuando alguien abre el CRM.

    Mismo motivo que en Calendly: la maquina de Fly se duerme sin trafico, asi
    que un cron interno no correria. Hilo aparte para no demorar la carga, y
    throttle para no consultar Notion en cada request.
    """
    if not os.environ.get("NOTION_TOKEN"):
        return
    now = time.time()
    with _notion_sync_lock:
        if now - _notion_sync_state["at"] < NOTION_SYNC_EVERY:
            return
        _notion_sync_state["at"] = now

    def _run():
        try:
            from services.notion_service import (traer_clientes, traer_proyectos,
                                                 traer_y_aplicar)
            try:
                np, error_p = traer_proyectos(db_path)
                if error_p:
                    logging.getLogger(__name__).warning("notion proyectos: %s", error_p)
                elif np:
                    logging.getLogger(__name__).info("notion sync: %s proyectos", np)
            except Exception:
                logging.getLogger(__name__).warning("notion proyectos falló", exc_info=True)

            try:
                nc, error_c = traer_clientes(db_path)
                if error_c:
                    logging.getLogger(__name__).warning("notion clientes: %s", error_c)
                elif nc:
                    logging.getLogger(__name__).info("notion sync: %s clientes", nc)
            except Exception:
                logging.getLogger(__name__).warning("notion clientes falló", exc_info=True)

            n, error = traer_y_aplicar(db_path)
            if error:
                logging.getLogger(__name__).warning("notion sync: %s", error)
            elif n:
                logging.getLogger(__name__).info("notion sync: %s tareas actualizadas", n)
        except Exception:
            logging.getLogger(__name__).warning("notion sync falló", exc_info=True)

    threading.Thread(target=_run, daemon=True).start()


def create_app(db_path: str) -> Flask:
    app = Flask(__name__)
    app.secret_key = os.environ.get("SECRET_KEY") or "scalerics-dev-key-change-in-prod"
    app.config["DB_PATH"] = db_path
    # Los envios que salen fuera de un request (los hilos de las campanas) se
    # registran en esta base para el panel Email marketing.
    from services.email_service import configurar_registro
    configurar_registro(db_path)
    # Cuando arranco este proceso. Lo usa /api/marketing/version para
    # poder contestar "¿estoy viendo lo ultimo?" sin entrar por SSH.
    import time as _t
    app._arrancado = int(_t.time())
    app.config["PIPELINE_STATUS"] = _pipeline_status
    app.config["PIPELINE_LOCK"] = _pipeline_lock

    for bp in (leads_bp, demos_bp, calendar_bp, wa_bp, pipeline_bp, tasks_bp, budgets_bp, tokens_bp, meta_bp, calendly_bp, notion_bp, projects_bp, preclientes_bp,
                notion_clients_bp, resend_bp, linkedin_bp, web_bp, finanzas_bp, marketing_bp,
                simulador_bp, equipo_bp, horarios_bp, flujos_bp, seg_leads_bp, daily_bp, plantillas_bp,
                backups_bp, email_mkt_bp, linkedin_panel_bp, linkedin_bot_bp, instagram_bp, instagram_pub_bp, sombra_bp,
                credenciales_bp, fidelidad_bp, plexo_bp):
        app.register_blueprint(bp)

    @app.before_request
    def require_login():
        if request.endpoint in ("login", "logout", "register", "forgot_password", "reset_password", "static", "privacidad", "baja_recordatorios"):
            return
        if request.path.startswith("/api/meta/webhook"):
            return
        if request.path.startswith("/api/calendly/webhook"):
            return
        # Su autenticacion es la firma de Svix, verificada dentro del endpoint:
        # Resend lo llama sin credenciales nuestras.
        if request.path.startswith("/api/resend/webhook"):
            return
        # Plexo: el link que abre el cliente para cargar la tarjeta, la página
        # de "listo" y el callback. No llevan sesión; routes/plexo.py no confía
        # en lo que reciben (ver su docstring).
        if request.path.startswith(PLEXO_PUBLICAS):
            return
        # La llama el navegador de cualquiera que descargue la guia de precios
        # del sitio: no puede llevar x-admin-token. Se valida sola por Origin
        # y tope por IP (ver routes/web.py).
        if request.path.startswith("/api/web/"):
            return
        # El link "ya lo publique" se abre desde un mail: no puede mandar headers,
        # asi que lleva su propio token de un solo uso en la query.
        if request.path.startswith("/api/linkedin/marcar"):
            return
        # Meta baja las imagenes de Instagram sin sesion. Cada publicacion tiene
        # su token al azar y solo se sirve mientras esta aprobada o saliendo.
        if request.path.startswith("/pub/ig/"):
            return
        # La sesion de Claude que corrige publicaciones: IG_BOT_TOKEN, que solo
        # abre estas rutas y se valida con compare_digest adentro del blueprint.
        if request.path.startswith("/api/instagram-bot/"):
            return
        # Lo mismo para LinkedIn: LINKEDIN_BOT_TOKEN, que solo abre estas rutas.
        if request.path.startswith("/api/linkedin-bot/"):
            return
        # El Apps Script del semaforo no puede llevar el ADMIN_TOKEN: vive pegado
        # a una planilla que es de la agencia, y cualquiera con permiso de
        # edicion sobre ella puede leer las Propiedades del script. Lleva
        # PLANILLA_TOKEN, que solo abre esta ruta. La validacion real —los dos
        # tokens, con compare_digest— esta adentro del endpoint, igual que en los
        # webhooks de arriba.
        if request.path.startswith("/api/meta/sync-planilla"):
            return
        # Any /api/ request with valid x-admin-token bypasses session auth
        if request.path.startswith("/api/"):
            token = request.headers.get("x-admin-token", "")
            expected = os.environ.get("ADMIN_TOKEN", "")
            if expected and token == expected:
                return
        # Invalidate pre-multiuser sessions that lack user_id
        if session.get("logged_in") and not session.get("user_id"):
            session.clear()
            if request.path.startswith("/api/"):
                return jsonify({"error": "session_expired"}), 401
            return redirect(url_for("login"))
        if not session.get("logged_in"):
            if request.path.startswith("/api/"):
                return jsonify({"error": "session_expired"}), 401
            return redirect(url_for("login"))

        # El vendedor de Fidelidad es de afuera de Scalerics: entra solo a sus
        # dos pantallas. El menu ya se las esconde, pero el candado es este:
        # las APIs del resto (agenda, leads, finanzas) no piden panel, y sin
        # esto un fetch a mano le mostraba las reuniones de la agencia.
        if (request.path.startswith("/api/") and request.path != "/api/me"
                and not request.path.startswith("/api/fidelidad/")):
            from services.fidelidad import es_vendedor
            if es_vendedor(app.config["DB_PATH"], session.get("user_id")):
                return jsonify({"ok": False, "error": "No autorizado"}), 403

        # Sesión válida: aprovechamos la visita para traer lo de Calendly.
        if not request.path.startswith(("/api/", "/static/")):
            _maybe_sync_calendly(app.config["DB_PATH"])
            _maybe_sync_notion(app.config["DB_PATH"])

